CREATE TABLE `identity_budget` (
	`identity_key` text NOT NULL,
	`day` text NOT NULL,
	`action` text NOT NULL,
	`used` integer DEFAULT 0 NOT NULL,
	PRIMARY KEY(`identity_key`, `day`, `action`)
);
